-- UNIBUD identity foundation
-- PostgreSQL migration: 0001_identity_foundation
-- IDs are generated by the trusted application/service layer.
-- Never insert real-user data into development or automated-test databases.

BEGIN;

CREATE TABLE accounts (
  id UUID PRIMARY KEY,
  status TEXT NOT NULL CHECK (status IN (
    'pending_verification', 'active', 'restricted', 'suspended', 'closed'
  )),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  closed_at TIMESTAMPTZ,
  CHECK ((status = 'closed') = (closed_at IS NOT NULL))
);

-- An identity is an authenticated subject, not the UNIBUD account itself.
-- identifier_ciphertext stores encrypted email/phone material where needed;
-- identifier_lookup_digest is a keyed digest for equality lookup, never a plain hash.
-- Do not store passwords, OTPs, recovery codes, access tokens or session secrets here.
CREATE TABLE authentication_identities (
  id UUID PRIMARY KEY,
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,
  issuer TEXT NOT NULL,
  subject TEXT NOT NULL,
  method TEXT NOT NULL CHECK (method IN ('email', 'phone', 'passkey', 'password')),
  identifier_ciphertext BYTEA,
  identifier_lookup_digest BYTEA,
  verified_at TIMESTAMPTZ,
  is_primary BOOLEAN NOT NULL DEFAULT false,
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'disabled', 'revoked')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (issuer, subject),
  UNIQUE (account_id, id),
  CHECK ((identifier_ciphertext IS NULL) = (identifier_lookup_digest IS NULL))
);

CREATE UNIQUE INDEX authentication_identity_primary_per_account
  ON authentication_identities(account_id)
  WHERE is_primary AND status = 'active';

CREATE INDEX authentication_identity_account_idx
  ON authentication_identities(account_id);


-- Store only a digest of a high-entropy opaque session credential.
-- The raw cookie/token is returned once to the client and is never persisted.
CREATE TABLE account_sessions (
  id UUID PRIMARY KEY,
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,
  credential_digest BYTEA NOT NULL UNIQUE,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'revoked')),
  issued_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen_at TIMESTAMPTZ,
  idle_expires_at TIMESTAMPTZ NOT NULL,
  absolute_expires_at TIMESTAMPTZ NOT NULL,
  revoked_at TIMESTAMPTZ,
  revocation_reason TEXT,
  rotated_from_session_id UUID REFERENCES account_sessions(id) ON DELETE RESTRICT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (octet_length(credential_digest) = 32),
  CHECK (idle_expires_at > issued_at),
  CHECK (absolute_expires_at > issued_at),
  CHECK (idle_expires_at <= absolute_expires_at),
  CHECK ((status = 'revoked') = (revoked_at IS NOT NULL))
);

CREATE INDEX account_sessions_account_active_idx
  ON account_sessions(account_id, issued_at DESC)
  WHERE status = 'active';

CREATE INDEX account_sessions_expiry_idx
  ON account_sessions(idle_expires_at, absolute_expires_at)
  WHERE status = 'active';

CREATE TABLE profiles (
  id UUID PRIMARY KEY,
  owner_account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,
  kind TEXT NOT NULL CHECK (kind IN ('personal', 'creator', 'page_community')),
  handle TEXT NOT NULL,
  handle_normalized TEXT NOT NULL UNIQUE,
  display_name TEXT NOT NULL,
  visibility TEXT NOT NULL DEFAULT 'private'
    CHECK (visibility IN ('private', 'limited', 'public')),
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'restricted', 'archived')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (owner_account_id, id)
);

CREATE INDEX profiles_owner_idx ON profiles(owner_account_id);

-- Membership is a relationship to one exact profile. It is not a global role.
CREATE TABLE profile_memberships (
  id UUID PRIMARY KEY,
  profile_id UUID NOT NULL REFERENCES profiles(id) ON DELETE RESTRICT,
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,
  owner_account_id UUID,
  relationship TEXT NOT NULL CHECK (relationship IN ('owner', 'delegated')),
  role TEXT NOT NULL CHECK (role IN (
    'owner', 'admin', 'moderator', 'editor', 'member', 'seller',
    'provider', 'professional', 'student', 'staff', 'operator', 'viewer'
  )),
  status TEXT NOT NULL CHECK (status IN ('pending', 'active', 'suspended', 'revoked')),
  can_switch_to_profile BOOLEAN NOT NULL DEFAULT false,
  granted_by_account_id UUID REFERENCES accounts(id) ON DELETE RESTRICT,
  granted_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  revoked_at TIMESTAMPTZ,
  UNIQUE (profile_id, account_id),
  FOREIGN KEY (owner_account_id, profile_id)
    REFERENCES profiles(owner_account_id, id) ON DELETE RESTRICT,
  CHECK ((relationship = 'owner' AND role = 'owner' AND can_switch_to_profile
          AND owner_account_id = account_id)
      OR (relationship = 'delegated' AND owner_account_id IS NULL)),
  CHECK ((status = 'revoked') = (revoked_at IS NOT NULL)),
  CHECK (relationship IN ('owner', 'delegated'))
);

CREATE INDEX profile_memberships_account_idx
  ON profile_memberships(account_id, status);
CREATE INDEX profile_memberships_profile_idx
  ON profile_memberships(profile_id, status);

-- Permissions are explicit, scoped to one application and one resource.
-- Roles alone never grant access. The authorisation service must evaluate actions.
CREATE TABLE resource_grants (
  id UUID PRIMARY KEY,
  subject_account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,
  application_id TEXT NOT NULL,
  resource_type TEXT NOT NULL,
  resource_id UUID NOT NULL,
  role TEXT NOT NULL,
  actions TEXT[] NOT NULL CHECK (
    cardinality(actions) > 0
    AND array_position(actions, NULL) IS NULL
    AND actions <@ ARRAY[
      'read', 'create', 'update', 'delete', 'publish', 'manage_members',
      'manage_billing', 'manage_integrations', 'dispatch', 'approve', 'export'
    ]::TEXT[]
  ),
  issued_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ,
  revoked_at TIMESTAMPTZ,
  issuer_account_id UUID REFERENCES accounts(id) ON DELETE RESTRICT,
  issuer_service TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (expires_at IS NULL OR expires_at > issued_at),
  CHECK (revoked_at IS NULL OR revoked_at >= issued_at),
  CHECK (issuer_account_id IS NOT NULL OR issuer_service IS NOT NULL)
);

CREATE INDEX resource_grants_subject_scope_idx
  ON resource_grants(subject_account_id, application_id, resource_type, resource_id)
  WHERE revoked_at IS NULL;

-- Append-only by application policy. Do not place credentials, message bodies,
-- financial payloads, or unnecessary personal data in event_data.
CREATE TABLE security_audit_events (
  id UUID PRIMARY KEY,
  occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  actor_account_id UUID REFERENCES accounts(id) ON DELETE RESTRICT,
  actor_service TEXT,
  application_id TEXT NOT NULL,
  action TEXT NOT NULL,
  outcome TEXT NOT NULL CHECK (outcome IN ('allowed', 'denied', 'success', 'failure')),
  resource_type TEXT,
  resource_id UUID,
  request_id TEXT,
  session_reference TEXT,
  reason_code TEXT,
  event_data JSONB NOT NULL DEFAULT '{}'::jsonb,
  CHECK (actor_account_id IS NOT NULL OR actor_service IS NOT NULL),
  CHECK (jsonb_typeof(event_data) = 'object')
);

CREATE INDEX security_audit_events_time_idx
  ON security_audit_events(occurred_at DESC);
CREATE INDEX security_audit_events_actor_idx
  ON security_audit_events(actor_account_id, occurred_at DESC)
  WHERE actor_account_id IS NOT NULL;
CREATE INDEX security_audit_events_resource_idx
  ON security_audit_events(resource_type, resource_id, occurred_at DESC)
  WHERE resource_id IS NOT NULL;

COMMENT ON TABLE accounts IS
  'Canonical UNIBUD account record; independent of login identifiers and profile families.';
COMMENT ON TABLE authentication_identities IS
  'Issuer-scoped authentication subjects; never store raw credentials or bearer secrets.';
COMMENT ON TABLE account_sessions IS
  'Server-side sessions; stores only a digest of a high-entropy opaque credential, never the raw token.';
COMMENT ON TABLE profiles IS
  'Distinct personal, creator and page/community profiles.';
COMMENT ON TABLE profile_memberships IS
  'Account-to-profile ownership or delegated relationship; exact-profile scope only.';
COMMENT ON TABLE resource_grants IS
  'Explicit app/resource/action grants; deny by default when no active matching grant exists.';
COMMENT ON TABLE security_audit_events IS
  'Security-relevant event history; application roles must not update or delete audit rows.';

-- Enforce append-only audit history at the database boundary as defence in depth.
CREATE FUNCTION reject_security_audit_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'security_audit_events is append-only';
END;
$$;

CREATE TRIGGER security_audit_events_no_update_or_delete
BEFORE UPDATE OR DELETE ON security_audit_events
FOR EACH ROW EXECUTE FUNCTION reject_security_audit_mutation();

COMMIT;
